/// Calculated Members (ECMA-376 Part 1 §18.10.1.11).
///
/// Represents the collection of calculated members in an OLAP PivotTable.
///
/// Schema type `CT_CalculatedMembers`, used by:
///
/// * `x:calculatedMembers` — Calculated Members (§18.10.1.11)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_CalculatedMembers {
    /// `count` — Calculated Members Count. Specifies the number of calculated members.
    pub count: Option<u32>,
    /// `x:calculatedMember` — Calculated Member (§18.10.1.10).
    pub calculated_member: Vec<CT_CalculatedMember>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_CalculatedMembers {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "count") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.count = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::X, "calculatedMember") => {
                        this.calculated_member.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.calculated_member.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_CalculatedMembers {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "count", &self.count);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.calculated_member.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::X, "calculatedMember");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.calculated_member.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_CalculatedMembers {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.calculated_member.iter().enumerate() {
            v.enter("x:calculatedMember", Some(i), |v| x.validate(v));
        }
        if self.calculated_member.is_empty() {
            v.required_element(Ns::X, "calculatedMember", &self.extra_children);
        }
    }
}

