/// Extension (ECMA-376 Part 1 §18.2.7).
///
/// Each extension within an extension list shall be contained within an ext element. Extensions shall be versioned by namespace, using the uri attribute, and shall be allowed to appear in any order within the extension list. Any number of extensions shall be allowed within an extension list.
///
/// Schema type `CT_Extension`, used by:
///
/// * `x:ext` — Extension (§18.2.7)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Extension {
    /// `uri` — URI. A token to identify version and application information for this particular extension.
    pub uri: Option<String>,
    /// Wildcard content (`xsd:any`), kept as raw XML.
    pub any: Option<RawElement>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Extension {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "uri") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.uri = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    _ => {
                        if pos <= 1 && this.any.is_none() && true {
                            this.any = Some(RawElement::read(r, &child)?);
                            pos = 1;
                        } else {
                            rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?);
                        }
                    }
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Extension {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "uri", &self.uri);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        if let Some(v) = &self.any {
            v.write(w);
        }
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_Extension {
    fn validate(&self, v: &mut Validator) {
        if self.any.is_none() {
            v.missing_content("an element (wildcard)");
        }
    }
}

/// Future Feature Data Storage Area (ECMA-376 Part 1 §18.2.10).
///
/// This element provides a convention for extending spreadsheetML in predefined locations. The locations shall be denoted with the extLst element, and are called extension lists. Extension list locations within the markup document are specified in the markup specification and can be used to store extensions to the markup specification, whether those are future version extensions of the markup specification or are private extensions implemented independently from the markup specification.
