/// Metadata String Store (ECMA-376 Part 1 §18.9.9).
///
/// This element represents the metadata string store. This is a collection of strings that are used as a resource for the rest of the metadata part. It contains all the required OLAP strings used in the spreadsheet including the connection name, as well as MDX expressions identifying specific members and sets.
///
/// Schema type `CT_MetadataStrings`, used by:
///
/// * `x:metadataStrings` — Metadata String Store (§18.9.9)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_MetadataStrings {
    /// `count` — MDX Metadata String Count. Number of records in the string store. Default: `0`.
    pub count: Option<u32>,
    /// `x:s` — Character Value (§18.13.8).
    pub s: Vec<CT_XStringElement>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_MetadataStrings {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "count") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.count = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::X, "s") => {
                        this.s.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.s.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_MetadataStrings {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "count", &self.count);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.s.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::X, "s");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.s.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_MetadataStrings {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.s.iter().enumerate() {
            v.enter("x:s", Some(i), |v| x.validate(v));
        }
        if self.s.is_empty() {
            v.required_element(Ns::X, "s", &self.extra_children);
        }
    }
}

/// Metadata Type Information (ECMA-376 Part 1 §18.9.10).
///
/// This element represents information about metadata on cells - it defines a specific set of behaviors that the metadata shall adhere to when subject to other spreadsheet operations. In general, many of these attributes represent operations that can be performed on a cell that allow the metadata to remain associated with the cell. Operations that are set to 0 or false, will cause the metadata to be disassociated from the cell when that operation is performed.
///
/// Schema type `CT_MetadataType`, used by:
///
/// * `x:metadataType` — Metadata Type Information (§18.9.10)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_MetadataType {
    /// `name` — Metadata Type Name. Represents the name of this particular metadata type. Required by the schema.
    pub name: Option<crate::shared_types::ST_Xstring>,
    /// `minSupportedVersion` attribute. Required by the schema.
    pub min_supported_version: Option<u32>,
    /// `ghostRow` — Metadata Ghost Row. A Boolean flag indicating whether metadata is copied to/from a ghost row. Default: `false`.
    pub ghost_row: Option<bool>,
    /// `ghostCol` — Metadata Ghost Column. A Boolean flag indicating whether metadata is copied to/from a ghost column. Default: `false`.
    pub ghost_col: Option<bool>,
    /// `edit` — Metadata Edit. A Boolean flag indicating whether metadata survives the editing of the cell's value. Default: `false`.
    pub edit: Option<bool>,
    /// `delete` — Metadata Cell Value Delete. A Boolean flag indicating whether metadata survives deletion of a cell value. Default: `false`.
    pub delete: Option<bool>,
    /// `copy` — Metadata Copy. A Boolean flag indicating whether metadata is copied with a cell. Default: `false`.
    pub copy: Option<bool>,
    /// `pasteAll` — Metadata Paste All. A Boolean flag indicating whether metadata is populated to a new cell by "Paste: All". Default: `false`.
    pub paste_all: Option<bool>,
    /// `pasteFormulas` — Metadata Paste Formulas. A Boolean flag indicating whether metadata is populated by Paste: Formulas. Default: `false`.
    pub paste_formulas: Option<bool>,
    /// `pasteValues` — Metadata Paste Special Values. A Boolean flag indicating whether metadata is populated by Paste: Values. Default: `false`.
    pub paste_values: Option<bool>,
    /// `pasteFormats` — Metadata Paste Formats. A Boolean flag indicating whether metadata is populated by Paste Special: Formats. Default: `false`.
    pub paste_formats: Option<bool>,
    /// `pasteComments` — Metadata Paste Comments. A Boolean flag indicating whether metadata is populated by Paste: Comments. Default: `false`.
    pub paste_comments: Option<bool>,
    /// `pasteDataValidation` attribute. Default: `false`.
    pub paste_data_validation: Option<bool>,
    /// `pasteBorders` — Metadata Paste Borders. A Boolean flag indicating whether metadata is populated with Paste: Borders. Default: `false`.
    pub paste_borders: Option<bool>,
    /// `pasteColWidths` — Metadata Paste Column Widths. A Boolean flag indicating whether metadata is populated by Paste: Column Widths. Default: `false`.
    pub paste_col_widths: Option<bool>,
    /// `pasteNumberFormats` attribute. Default: `false`.
    pub paste_number_formats: Option<bool>,
    /// `merge` — Metadata Merge. A Boolean flag indicating whether metadata survives cell merge. Default: `false`.
    pub merge: Option<bool>,
    /// `splitFirst` — Meatadata Split First. A Boolean flag indicating whether when a merged cell is split its metadata is copied to only the first resulting cell. Default: `false`.
    pub split_first: Option<bool>,
    /// `splitAll` — Metadata Split All. A Boolean flag indicating whether a merged cell split action has its metadata copied to all of the resulting cells. Default: `false`.
    pub split_all: Option<bool>,
    /// `rowColShift` — Metadata Insert Delete. A Boolean flag indicating whether metadata survives shifting due to row/column insertion/deletion. Default: `false`.
    pub row_col_shift: Option<bool>,
    /// `clearAll` — Metadata Clear All. A Boolean flag indicating whether metadata survives a "Clear: All" operation. Default: `false`.
    pub clear_all: Option<bool>,
    /// `clearFormats` — Metadata Clear Formats. A Boolean flag indicating whether metadata remains after formatting is removed from a cell. Default: `false`.
    pub clear_formats: Option<bool>,
    /// `clearContents` — Metadata Clear Contents. A Boolean flag indicating whether metadata remains after the contents of a cell are removed. Default: `false`.
    pub clear_contents: Option<bool>,
    /// `clearComments` — Metadata Clear Comments. A Boolean flag indicating whether metadata remains after comments have been cleared from the cell. Default: `false`.
    pub clear_comments: Option<bool>,
    /// `assign` — Metadata Formula Assignment. A Boolean flag indicating whether metadata is propagated by formula assignment operation. Default: `false`.
    pub assign: Option<bool>,
    /// `coerce` — Metadata Coercion. A Boolean flag indicating whether value metadata can be removed when this metadata data type is coerced to another data type. Default: `false`.
    pub coerce: Option<bool>,
    /// `adjust` — Adjust Metadata. A Boolean flag indicating that metadata corresponding to a particular cell needs to be notified when that cell's location is changed. Default: `false`.
    pub adjust: Option<bool>,
    /// `cellMeta` — Cell Metadata. A Boolean flag indicating whether metadata is cell metadata. Default: `false`.
    pub cell_meta: Option<bool>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

