/// PivotTable Fields (ECMA-376 Part 1 §18.10.1.70).
///
/// Represents the collection of fields that appear on the PivotTable.
///
/// Schema type `CT_PivotFields`, used by:
///
/// * `x:pivotFields` — PivotTable Fields (§18.10.1.70)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_PivotFields {
    /// `count` — Field Count. Specifies the number of fields in the PivotTable.
    pub count: Option<u32>,
    /// `x:pivotField` — PivotTable Field (§18.10.1.69).
    pub pivot_field: Vec<CT_PivotField>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_PivotFields {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "count") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.count = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::X, "pivotField") => {
                        this.pivot_field.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.pivot_field.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_PivotFields {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "count", &self.count);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.pivot_field.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::X, "pivotField");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.pivot_field.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_PivotFields {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.pivot_field.iter().enumerate() {
            v.enter("x:pivotField", Some(i), |v| x.validate(v));
        }
        if self.pivot_field.is_empty() {
            v.required_element(Ns::X, "pivotField", &self.extra_children);
        }
    }
}

