/// Tables (ECMA-376 Part 1 §18.13.9).
///
/// This element serves as the collection of tables to be returned via a web query data connection. Tables are then most commonly referenced by &lt;x&gt; via their indices (in order of the &lt;Table&gt; tags in the HTML page).
///
/// Schema type `CT_Tables`, used by:
///
/// * `x:tables` — Tables (§18.13.9)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Tables {
    /// `count` — Count of Tables. Number of tables to pull data from when refreshing from a web query.
    pub count: Option<u32>,
    /// Child elements of choice [`CT_Tables_Choice`](crate::sml::CT_Tables_Choice).
    pub choice: Vec<CT_Tables_Choice>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Tables {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "count") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.count = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::X, "m") | (Ns::X, "s") | (Ns::X, "x") => {
                        this.choice.push(CT_Tables_Choice::read_choice(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => this
                            .choice
                            .push(CT_Tables_Choice::Other(Box::new(RawElement::read(r, &child)?))),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Tables {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "count", &self.count);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        for v in &self.choice {
            v.write_choice(w);
        }
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_Tables {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.choice.iter().enumerate() {
            x.validate_at(v, Some(i));
        }
        if self.choice.is_empty() {
            v.missing_content("one of x:m, x:s, x:x");
        }
    }
}

