/// Sort By Tuple (ECMA-376 Part 1 §18.10.1.91).
///
/// Represents the sort applied to a tuple.
///
/// Schema type `CT_Tuples`, used by:
///
/// * `x:sortByTuple` — Sort By Tuple (§18.10.1.91)
/// * `x:tpls` — Tuples (§18.10.1.93)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Tuples {
    /// `c` — Member Name Count. Specifies the number of member names.
    pub c: Option<u32>,
    /// `x:tpl` — Tuple (§18.10.1.92).
    pub tpl: Vec<CT_Tuple>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Tuples {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "c") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.c = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::X, "tpl") => {
                        this.tpl.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.tpl.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Tuples {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "c", &self.c);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.tpl.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::X, "tpl");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.tpl.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_Tuples {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.tpl.iter().enumerate() {
            v.enter("x:tpl", Some(i), |v| x.validate(v));
        }
        if self.tpl.is_empty() {
            v.required_element(Ns::X, "tpl", &self.extra_children);
        }
    }
}

